body .chat-detail-screen .bubble-me-custom:has(img) .msg-image-card img,
body .chat-detail-screen .bubble-them-custom:has(img) .msg-image-card img {
  width: 100% !important;
  height: 100% !important;
  max-width: none !important;
  max-height: none !important;
  object-fit: cover !important;
  border-radius: var(--st-r) !important;
